### ✅ Example 1 — The Classic Refactor: Inheritance → Composition

```python name=example1_inheritance_to_composition.py
# ══════════════════════════════════════════════════
#  PROBLEM: Wrong use of inheritance
#  SOLUTION: Refactor to composition
# ══════════════════════════════════════════════════

# ─── ❌ WRONG: Inheritance misused ───
print("=" * 55)
print("❌ WRONG: Inheritance-based design")
print("=" * 55)

class WrongEmailService_SMTP:
    """Simulated SMTP"""
    def connect(self, host, port):
        print(f"  🔌 SMTP connecting to {host}:{port}")
    def authenticate(self, user, pwd):
        print(f"  🔐 Authenticating as {user}")
    def send_raw(self, frm, to, subject, body):
        print(f"  📧 SMTP sending: {subject} → {to}")
    def disconnect(self):
        print(f"  ❌ SMTP disconnected")

# EmailService inherits from SMTP — WRONG!
# EmailService IS NOT an SMTP connection!
class WrongEmailService(WrongEmailService_SMTP):
    def __init__(self, host, port, user, password):
        self.host = host
        self.port = port
        self.user = user
        self.password = password
        self.connect(host, port)       # inherited
        self.authenticate(user, password)

    def send_email(self, to, subject, body):
        self.send_raw(self.user, to, subject, body)

# Problems:
# 1. Can't switch SMTP providers without rewriting WrongEmailService
# 2. All SMTP internals exposed to callers of EmailService
# 3. EmailService "IS-A" SMTP? Makes no semantic sense
# 4. Unit testing is a nightmare — can't inject mock SMTP

wrong = WrongEmailService("smtp.gmail.com", 587, "me@gmail.com", "password")
wrong.send_email("alice@test.com", "Hello", "World")
wrong.connect("other.smtp.com", 25)  # EXPOSED! Callers can mess with SMTP!

# ─── ✅ RIGHT: Composition ───
print("\n" + "=" * 55)
print("✅ RIGHT: Composition-based design")
print("=" * 55)

class SMTPProvider:
    """SMTP connection handler — standalone"""
    def __init__(self, host, port):
        self.host = host
        self.port = port
    def connect(self):
        print(f"  🔌 {self.__class__.__name__} connecting to {self.host}:{self.port}")
    def authenticate(self, user, pwd):
        print(f"  🔐 Authenticating {user}")
    def send(self, frm, to, subject, body):
        print(f"  📧 Sending: [{subject}] to {to}")
    def disconnect(self):
        print(f"  ❌ {self.__class__.__name__} disconnected")

class SendGridProvider(SMTPProvider):
    """Alternative provider — same interface"""
    def send(self, frm, to, subject, body):
        print(f"  📧 SendGrid API: [{subject}] to {to}")

class SESProvider(SMTPProvider):
    """AWS SES provider"""
    def send(self, frm, to, subject, body):
        print(f"  📧 AWS SES: [{subject}] to {to}")

class EmailService:
    """Composes an SMTP provider — doesn't inherit from it"""

    def __init__(self, smtp_provider: SMTPProvider,
                 sender_email: str):
        self._smtp   = smtp_provider    # HAS-A
        self._sender = sender_email
        self._smtp.connect()

    def send_email(self, to: str, subject: str, body: str):
        """Public interface — hides SMTP details"""
        self._smtp.send(self._sender, to, subject, body)
        print(f"  ✅ Email delivered!")

    def send_bulk(self, recipients: list, subject: str, body: str):
        for recipient in recipients:
            self.send_email(recipient, subject, body)

    def switch_provider(self, new_provider: SMTPProvider):
        """CAN switch providers at runtime — impossible with inheritance!"""
        print(f"\n  🔄 Switching from {type(self._smtp).__name__} "
              f"to {type(new_provider).__name__}")
        self._smtp.disconnect()
        self._smtp = new_provider
        self._smtp.connect()

    # SMTP internals are HIDDEN — callers can't accidentally call connect()

# Benefits:
gmail_smtp = SMTPProvider("smtp.gmail.com", 587)
email_svc  = EmailService(gmail_smtp, "me@gmail.com")
email_svc.send_email("alice@test.com", "Hello", "Hi Alice!")

# Switch provider at runtime — zero code change in EmailService!
sendgrid   = SendGridProvider("smtp.sendgrid.net", 587)
email_svc.switch_provider(sendgrid)
email_svc.send_email("bob@test.com", "Invoive", "See attached.")

# SMTP details are hidden:
# email_svc.connect()  → AttributeError! ✅ GOOD — users can't misuse it

# ─── Testability comparison ───
print("\n=== Testing with Composition (easy!) ===")

class MockSMTP(SMTPProvider):
    def __init__(self):
        self.sent_emails = []
    def connect(self):      pass   # no-op
    def disconnect(self):   pass
    def authenticate(self, u, p): pass
    def send(self, frm, to, subject, body):
        self.sent_emails.append({"to": to, "subject": subject})
        print(f"  📧 [MOCK] Recorded email to {to}")

mock_smtp = MockSMTP()
test_svc  = EmailService(mock_smtp, "test@example.com")
test_svc.send_bulk(["a@t.com", "b@t.com", "c@t.com"], "Test", "Body")
print(f"\nEmails sent in test: {len(mock_smtp.sent_emails)}")
assert len(mock_smtp.sent_emails) == 3
print("✅ Test passed!")
```

### ✅ Example 2 — Strategy Pattern (Composition for Interchangeable Behaviours)

```python name=example2_strategy_pattern.py
# ══════════════════════════════════════════════════
#  STRATEGY PATTERN — Composition at its finest
#  Inject different "strategies" (behaviours) at runtime
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod

# ─── Strategy interfaces ───
class SortStrategy(ABC):
    @abstractmethod
    def sort(self, data: list) -> list: pass
    @abstractmethod
    def name(self) -> str: pass

class DiscountStrategy(ABC):
    @abstractmethod
    def calculate(self, price: float, quantity: int) -> float: pass
    @abstractmethod
    def description(self) -> str: pass

class ShippingStrategy(ABC):
    @abstractmethod
    def calculate_cost(self, weight_kg: float, distance_km: float) -> float: pass
    @abstractmethod
    def estimated_days(self) -> int: pass

# ─── Sorting strategies ───
class BubbleSortStrategy(SortStrategy):
    def sort(self, data):
        arr = data.copy()
        n   = len(arr)
        for i in range(n):
            for j in range(n-i-1):
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
        return arr
    def name(self): return "Bubble Sort O(n²)"

class QuickSortStrategy(SortStrategy):
    def sort(self, data):
        if len(data) <= 1: return data
        pivot = data[len(data)//2]
        left  = [x for x in data if x < pivot]
        mid   = [x for x in data if x == pivot]
        right = [x for x in data if x > pivot]
        return self.sort(left) + mid + self.sort(right)
    def name(self): return "Quick Sort O(n log n)"

class BuiltinSortStrategy(SortStrategy):
    def sort(self, data): return sorted(data)
    def name(self): return "Python built-in (TimSort)"

# ─── Discount strategies ───
class NoDiscount(DiscountStrategy):
    def calculate(self, price, quantity): return price * quantity
    def description(self): return "No discount"

class PercentageDiscount(DiscountStrategy):
    def __init__(self, percent): self.percent = percent
    def calculate(self, price, quantity):
        return price * quantity * (1 - self.percent/100)
    def description(self): return f"{self.percent}% discount"

class BulkDiscount(DiscountStrategy):
    def __init__(self, threshold, percent):
        self.threshold = threshold
        self.percent   = percent
    def calculate(self, price, quantity):
        if quantity >= self.threshold:
            return price * quantity * (1 - self.percent/100)
        return price * quantity
    def description(self):
        return f"{self.percent}% off on {self.threshold}+ units"

class TieredDiscount(DiscountStrategy):
    TIERS = [(100, 20), (50, 15), (20, 10), (10, 5), (0, 0)]
    def calculate(self, price, quantity):
        for min_qty, pct in self.TIERS:
            if quantity >= min_qty:
                return price * quantity * (1 - pct/100)
        return price * quantity
    def description(self): return "Tiered: 5%/10%/15%/20% by quantity"

# ─── Shipping strategies ───
class StandardShipping(ShippingStrategy):
    def calculate_cost(self, weight, distance):
        return max(50, weight * 10 + distance * 0.5)
    def estimated_days(self): return 7

class ExpressShipping(ShippingStrategy):
    def calculate_cost(self, weight, distance):
        return max(150, weight * 25 + distance * 1.5)
    def estimated_days(self): return 2

class FreeShipping(ShippingStrategy):
    def calculate_cost(self, weight, distance): return 0
    def estimated_days(self): return 10

# ─── Context: Order uses COMPOSED strategies ───
class Order:
    """
    Order composes 3 strategies.
    Switch any strategy at runtime — no class changes needed!
    """

    def __init__(self, items: list,
                 discount_strategy:  DiscountStrategy  = None,
                 shipping_strategy:  ShippingStrategy  = None,
                 sort_strategy:      SortStrategy      = None):

        self.items            = items
        self._discount        = discount_strategy  or NoDiscount()
        self._shipping        = shipping_strategy  or StandardShipping()
        self._sort            = sort_strategy      or BuiltinSortStrategy()

    def set_discount(self, strategy: DiscountStrategy):
        """Swap strategy at runtime!"""
        print(f"  🔄 Discount: {self._discount.description()} → {strategy.description()}")
        self._discount = strategy

    def set_shipping(self, strategy: ShippingStrategy):
        print(f"  🔄 Shipping changed to: {strategy.__class__.__name__}")
        self._shipping = strategy

    def get_sorted_items(self):
        prices = [item['price'] for item in self.items]
        return self._sort.sort(prices)

    def calculate_total(self, weight_kg=1.0, distance_km=500):
        unit_price    = sum(i['price'] for i in self.items)
        quantity      = sum(i['qty'] for i in self.items)
        subtotal      = self._discount.calculate(unit_price, quantity)
        shipping_cost = self._shipping.calculate_cost(weight_kg, distance_km)
        return {
            "subtotal"      : round(subtotal, 2),
            "shipping"      : round(shipping_cost, 2),
            "total"         : round(subtotal + shipping_cost, 2),
            "discount_info" : self._discount.description(),
            "shipping_days" : self._shipping.estimated_days(),
            "sort_algo"     : self._sort.name(),
        }

    def print_receipt(self, weight=1.0, distance=500):
        totals = self.calculate_total(weight, distance)
        print(f"\n  🧾 ORDER RECEIPT")
        print(f"  {'─'*40}")
        for k, v in totals.items():
            label = k.replace('_', ' ').title()
            val   = f"₹{v:,.2f}" if isinstance(v, float) else str(v)
            print(f"  {label:<20}: {val}")
        print(f"  {'─'*40}")

# ─── Testing Strategy Pattern ───
items = [
    {"name": "Laptop", "price": 75000, "qty": 2},
    {"name": "Mouse",  "price": 1500,  "qty": 5},
]

print("=== Order with default strategies ===")
order = Order(items)
order.print_receipt()

print("\n=== Switch to bulk discount + express shipping ===")
order.set_discount(BulkDiscount(threshold=3, percent=15))
order.set_shipping(ExpressShipping())
order.print_receipt(weight=3.5, distance=800)

print("\n=== High-volume: tiered discount + free shipping ===")
order.set_discount(TieredDiscount())
order.set_shipping(FreeShipping())
order.print_receipt()

print("\n=== Sorting strategies compared ===")
data = [64, 34, 25, 12, 22, 11, 90]
for strategy in [BubbleSortStrategy(), QuickSortStrategy(), BuiltinSortStrategy()]:
    result = strategy.sort(data)
    print(f"  {strategy.name():<30}: {result}")
```

### ✅ Example 3 — Composition for Flexible Object Building

```python name=example3_composition_builder.py
# ══════════════════════════════════════════════════
#  COMPOSITION FOR FLEXIBILITY
#  Building complex objects from simple components
# ══════════════════════════════════════════════════

class Engine:
    """Component: Engine"""
    def __init__(self, type_, horsepower, torque_nm):
        self.type_      = type_
        self.horsepower = horsepower
        self.torque_nm  = torque_nm
        self._running   = False

    def start(self):
        self._running = True
        print(f"  🔧 {self.type_} engine started ({self.horsepower}hp)")

    def stop(self):
        self._running = False
        print(f"  🔧 Engine stopped")

    def get_power_output(self):
        return self.horsepower * 0.75 if self._running else 0

    def __repr__(self):
        return f"Engine({self.type_}, {self.horsepower}hp)"

class Battery:
    """Component: EV Battery"""
    def __init__(self, capacity_kwh, max_range_km):
        self.capacity_kwh  = capacity_kwh
        self.max_range_km  = max_range_km
        self._charge_pct   = 100.0

    def charge(self, amount_pct):
        self._charge_pct = min(100, self._charge_pct + amount_pct)
        print(f"  🔋 Battery charged to {self._charge_pct:.1f}%")

    def discharge(self, amount_pct):
        self._charge_pct = max(0, self._charge_pct - amount_pct)

    @property
    def current_range_km(self):
        return self.max_range_km * (self._charge_pct / 100)

    def __repr__(self):
        return f"Battery({self.capacity_kwh}kWh, {self._charge_pct:.0f}%)"

class GPS:
    """Component: GPS Navigation"""
    def __init__(self, provider="Google Maps"):
        self.provider   = provider
        self._active    = False
        self._route     = None

    def navigate_to(self, destination):
        self._active = True
        self._route  = destination
        print(f"  🗺️  {self.provider}: Navigating to {destination}")

    def stop_navigation(self):
        self._active = False
        self._route  = None

    def get_eta(self, current_speed_kmh):
        if self._route and current_speed_kmh > 0:
            distance = 50  # simulated
            return f"{distance/current_speed_kmh*60:.0f} minutes to {self._route}"
        return "Navigation inactive"

class AudioSystem:
    """Component: Audio System"""
    def __init__(self, brand, num_speakers):
        self.brand        = brand
        self.num_speakers = num_speakers
        self._volume      = 50
        self._playing     = None

    def play(self, track):
        self._playing = track
        print(f"  🎵 {self.brand} ({self.num_speakers} speakers): {track}")

    def set_volume(self, level):
        self._volume = max(0, min(100, level))
        print(f"  🔊 Volume: {self._volume}%")

class SafetySystem:
    """Component: Safety features"""
    def __init__(self, has_abs, has_airbags, has_esp):
        self.has_abs     = has_abs
        self.has_airbags = has_airbags
        self.has_esp     = has_esp

    def emergency_brake(self):
        if self.has_abs:
            print("  🛑 ABS activated — emergency braking!")
        else:
            print("  🛑 Emergency braking (no ABS)")

    def safety_report(self):
        return {
            "ABS"    : "✅" if self.has_abs     else "❌",
            "Airbags": "✅" if self.has_airbags  else "❌",
            "ESP"    : "✅" if self.has_esp      else "❌",
        }

# ─── Cars composed from components ───
class Car:
    """
    Car COMPOSES components instead of inheriting from them.
    Different car models get different component combinations.
    """

    def __init__(self, make, model, year,
                 engine: Engine,
                 safety: SafetySystem,
                 gps: GPS = None,
                 audio: AudioSystem = None,
                 battery: Battery = None):

        self.make   = make
        self.model  = model
        self.year   = year
        self.speed  = 0

        # Composed components — HAS-A relationships
        self.engine  = engine      # required
        self.safety  = safety      # required
        self.gps     = gps         # optional
        self.audio   = audio       # optional
        self.battery = battery     # optional (EVs only)

    @property
    def is_electric(self):
        return self.battery is not None

    @property
    def is_hybrid(self):
        return self.battery is not None and self.engine is not None

    def start(self):
        print(f"\n  🚗 Starting {self.year} {self.make} {self.model}")
        self.engine.start()

    def accelerate(self, kmh):
        self.speed = min(self.speed + kmh, 250)
        print(f"  ⬆️  Speed: {self.speed} km/h")
        if self.battery:
            self.battery.discharge(kmh * 0.01)

    def emergency_stop(self):
        self.safety.emergency_brake()
        self.speed = 0

    def navigate(self, destination):
        if self.gps:
            self.gps.navigate_to(destination)
            print(f"  ℹ️  ETA: {self.gps.get_eta(self.speed)}")
        else:
            print("  ❌ No GPS installed")

    def play_music(self, track):
        if self.audio:
            self.audio.play(track)
        else:
            print("  ❌ No audio system")

    def info(self):
        print(f"\n  {'='*45}")
        print(f"  🚗 {self.year} {self.make} {self.model}")
        print(f"  {'─'*45}")
        print(f"  Engine  : {self.engine}")
        print(f"  Battery : {self.battery or 'None (ICE)'}")
        print(f"  GPS     : {self.gps.provider if self.gps else 'Not installed'}")
        print(f"  Audio   : {self.audio.brand if self.audio else 'Basic'}")
        safety  = self.safety.safety_report()
        print(f"  Safety  : ABS={safety['ABS']} Airbags={safety['Airbags']} ESP={safety['ESP']}")
        print(f"  Type    : {'Electric' if self.is_electric else 'Petrol/Diesel'}")
        print(f"  {'='*45}")

# ─── Build different cars from same components ───

# Budget car — minimal components
budget_car = Car(
    make   = "Maruti", model = "Alto", year = 2024,
    engine = Engine("Petrol", 67, 89),
    safety = SafetySystem(has_abs=False, has_airbags=True, has_esp=False),
)

# Premium car — all features
premium_car = Car(
    make    = "BMW",  model = "5 Series", year = 2025,
    engine  = Engine("TwinTurbo Petrol", 335, 450),
    safety  = SafetySystem(True, True, True),
    gps     = GPS("BMW Navigation"),
    audio   = AudioSystem("Harman Kardon", 16),
)

# Electric car — battery instead of fuel engine
electric_car = Car(
    make    = "Tata", model = "Nexon EV", year = 2025,
    engine  = Engine("Electric Motor", 143, 250),
    battery = Battery(capacity_kwh=40, max_range_km=437),
    safety  = SafetySystem(True, True, True),
    gps     = GPS("MapMyIndia"),
    audio   = AudioSystem("JBL", 9),
)

# Display all
for car in [budget_car, premium_car, electric_car]:
    car.info()

# Use premium
print("\n=== Premium Car Drive ===")
premium_car.start()
premium_car.accelerate(80)
premium_car.navigate("Mumbai Airport")
premium_car.play_music("Discover Weekly Playlist")
premium_car.emergency_stop()
```

### ✅ Example 4 — When Inheritance IS Right

```python name=example4_when_inheritance_is_right.py
# ══════════════════════════════════════════════════
#  WHEN INHERITANCE IS THE RIGHT CHOICE
#  True IS-A relationships + LSP satisfaction
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod

# ─── Case 1: Domain Model Hierarchy (True IS-A) ───
class BankAccount(ABC):
    """Every BankAccount IS-A... bank account. Correct hierarchy."""

    def __init__(self, account_no, holder, initial_balance=0):
        self.account_no = account_no
        self.holder     = holder
        self._balance   = float(initial_balance)
        self._history   = []

    @property
    def balance(self):
        return self._balance

    @abstractmethod
    def calculate_interest(self) -> float:
        """Each account type has different interest calculation"""
        pass

    @abstractmethod
    def get_account_type(self) -> str:
        pass

    # Concrete shared behaviour — ALL accounts share this
    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit must be positive")
        self._balance += amount
        self._log(f"DEPOSIT ₹{amount:,}")
        print(f"  ✅ Deposited ₹{amount:,}. Balance: ₹{self._balance:,}")

    def get_statement(self):
        print(f"\n  {'='*50}")
        print(f"  {self.get_account_type()} — {self.holder}")
        print(f"  A/C: {self.account_no} | Balance: ₹{self._balance:,}")
        print(f"  {'─'*50}")
        for entry in self._history[-5:]:
            print(f"    {entry}")
        print(f"  {'='*50}")

    def _log(self, entry):
        from datetime import datetime
        self._history.append(f"[{datetime.now().strftime('%H:%M:%S')}] {entry}")

class SavingsAccount(BankAccount):
    """SavingsAccount IS-A BankAccount ✅"""

    INTEREST_RATE = 0.035  # 3.5% p.a.

    def __init__(self, account_no, holder, initial_balance=0,
                 min_balance=500):
        super().__init__(account_no, holder, initial_balance)
        self.min_balance = min_balance

    def calculate_interest(self) -> float:
        return round(self._balance * self.INTEREST_RATE / 12, 2)

    def get_account_type(self) -> str:
        return "Savings Account"

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Must be positive")
        if self._balance - amount < self.min_balance:
            raise ValueError(
                f"Cannot go below minimum balance ₹{self.min_balance:,}"
            )
        self._balance -= amount
        self._log(f"WITHDRAWAL ₹{amount:,}")
        print(f"  ✅ Withdrew ₹{amount:,}. Balance: ₹{self._balance:,}")

    def add_monthly_interest(self):
        interest = self.calculate_interest()
        self.deposit(interest)
        print(f"  💰 Monthly interest added: ₹{interest:,}")

class CurrentAccount(BankAccount):
    """CurrentAccount IS-A BankAccount ✅"""

    def __init__(self, account_no, holder, initial_balance=0,
                 overdraft_limit=50000):
        super().__init__(account_no, holder, initial_balance)
        self.overdraft_limit = overdraft_limit

    def calculate_interest(self) -> float:
        return 0.0  # No interest on current accounts

    def get_account_type(self) -> str:
        return "Current Account"

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Must be positive")
        if self._balance - amount < -self.overdraft_limit:
            raise ValueError(
                f"Exceeds overdraft limit of ₹{self.overdraft_limit:,}"
            )
        self._balance -= amount
        self._log(f"WITHDRAWAL ₹{amount:,}"
                  + (" [OVERDRAFT]" if self._balance < 0 else ""))
        print(f"  ✅ Withdrew ₹{amount:,}. Balance: ₹{self._balance:,}"
              + (" ⚠️ OVERDRAFT" if self._balance < 0 else ""))

class FixedDeposit(BankAccount):
    """FixedDeposit IS-A BankAccount ✅"""

    def __init__(self, account_no, holder, principal,
                 rate_pa, duration_months):
        super().__init__(account_no, holder, principal)
        self.rate_pa          = rate_pa
        self.duration_months  = duration_months

    def calculate_interest(self) -> float:
        return round(self._balance * self.rate_pa * self.duration_months / 1200, 2)

    def get_account_type(self) -> str:
        return f"Fixed Deposit ({self.rate_pa}% for {self.duration_months}mo)"

    def maturity_amount(self):
        return self._balance + self.calculate_interest()

# ─── Liskov Substitution: any BankAccount works here ───
def process_month_end(accounts: list):
    """Works with ANY BankAccount subclass — LSP in action"""
    print("\n  📅 MONTH-END PROCESSING")
    for acc in accounts:
        interest = acc.calculate_interest()
        print(f"  {acc.get_account_type():<30} "
              f"Balance: ₹{acc.balance:>10,.2f} | "
              f"Interest: ₹{interest:>8,.2f}")

accounts = [
    SavingsAccount("SB001", "Alice", 50000),
    SavingsAccount("SB002", "Bob",   25000),
    CurrentAccount("CA001", "Corp",  100000, overdraft_limit=200000),
    FixedDeposit  ("FD001", "Carol", 200000, rate_pa=6.5, duration_months=12),
]

