### ✅ Example 5 — Mixing Composition AND Inheritance Correctly

```python name=example5_mixed_correctly.py
# ══════════════════════════════════════════════════
#  THE REAL WORLD: Inheritance AND Composition together
#  Use each where appropriate in the same system
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod
from datetime import datetime

# ─── Composed components (not inherited!) ───
class NotificationChannel:
    """Component that Order COMPOSES — not inherits"""
    def notify(self, recipient, message): pass

class EmailChannel(NotificationChannel):
    def notify(self, recipient, message):
        print(f"  📧 EMAIL → {recipient}: {message}")

class SMSChannel(NotificationChannel):
    def notify(self, recipient, message):
        print(f"  📱 SMS  → {recipient}: {message}")

class PushChannel(NotificationChannel):
    def notify(self, recipient, message):
        print(f"  🔔 PUSH → {recipient}: {message}")

class PaymentProcessor:
    """Component that Order COMPOSES"""
    def process(self, amount): pass

class RazorpayProcessor(PaymentProcessor):
    def process(self, amount):
        print(f"  💳 Razorpay: Processing ₹{amount:,}")
        return {"status": "success", "txn": f"rzp_{id(self)}"}

class StripeProcessor(PaymentProcessor):
    def process(self, amount):
        print(f"  💳 Stripe: Processing ₹{amount:,}")
        return {"status": "success", "txn": f"ch_{id(self)}"}

class TaxCalculator:
    """Component: tax computation"""
    def __init__(self, rate):
        self.rate = rate
    def compute(self, subtotal):
        return round(subtotal * self.rate, 2)

# ─── Inheritance hierarchy (true IS-A) ───
class BaseOrder(ABC):
    """Abstract base — all orders ARE orders"""

    def __init__(self, order_id, customer_name,
                 payment_proc: PaymentProcessor,
                 notifier: NotificationChannel,
                 tax_calc: TaxCalculator):
        self.order_id      = order_id
        self.customer_name = customer_name
        self._items        = []
        self._status       = "pending"
        self._created_at   = datetime.now()

        # COMPOSED components — NOT inherited
        self._payment   = payment_proc
        self._notifier  = notifier
        self._tax_calc  = tax_calc

    def add_item(self, name, price, qty=1):
        self._items.append({"name": name, "price": price, "qty": qty})

    @property
    def subtotal(self):
        return sum(i['price'] * i['qty'] for i in self._items)

    @property
    def tax(self):
        return self._tax_calc.compute(self.subtotal)

    @property
    def total(self):
        return self.subtotal + self.tax + self.shipping_cost

    @property
    @abstractmethod
    def shipping_cost(self) -> float:
        pass

    @abstractmethod
    def get_order_type(self) -> str:
        pass

    def place(self):
        print(f"\n  🛒 Placing {self.get_order_type()} #{self.order_id}")
        result = self._payment.process(self.total)
        if result['status'] == 'success':
            self._status = "confirmed"
            self._notifier.notify(
                self.customer_name,
                f"Order #{self.order_id} confirmed! Total: ₹{self.total:,}"
            )
            print(f"  ✅ Order placed! TXN: {result['txn']}")
        return result

    def print_summary(self):
        print(f"\n  {'='*45}")
        print(f"  {self.get_order_type()} #{self.order_id}")
        print(f"  Customer  : {self.customer_name}")
        print(f"  Status    : {self._status}")
        print(f"  Items     : {len(self._items)}")
        print(f"  Subtotal  : ₹{self.subtotal:>10,.2f}")
        print(f"  Tax       : ₹{self.tax:>10,.2f}")
        print(f"  Shipping  : ₹{self.shipping_cost:>10,.2f}")
        print(f"  Total     : ₹{self.total:>10,.2f}")
        print(f"  {'='*45}")

class RetailOrder(BaseOrder):
    """RetailOrder IS-A BaseOrder ✅ (true IS-A)"""

    SHIPPING_RATE = 99

    @property
    def shipping_cost(self):
        return 0 if self.subtotal > 999 else self.SHIPPING_RATE

    def get_order_type(self): return "Retail Order"

class WholesaleOrder(BaseOrder):
    """WholesaleOrder IS-A BaseOrder ✅"""

    def __init__(self, *args, min_order_value=10000, **kwargs):
        super().__init__(*args, **kwargs)
        self.min_order_value = min_order_value

    @property
    def shipping_cost(self): return 0   # free shipping for wholesale

    def get_order_type(self): return "Wholesale Order"

    def place(self):
        if self.subtotal < self.min_order_value:
            raise ValueError(
                f"Minimum wholesale order: ₹{self.min_order_value:,}"
            )
        return super().place()

class SubscriptionOrder(BaseOrder):
    """SubscriptionOrder IS-A BaseOrder ✅"""

    def __init__(self, *args, frequency="monthly", **kwargs):
        super().__init__(*args, **kwargs)
        self.frequency = frequency

    @property
    def shipping_cost(self): return 0  # subscribers get free shipping

    def get_order_type(self): return f"Subscription ({self.frequency})"

# ─── Testing the mixed system ───
# Choose components
razorpay = RazorpayProcessor()
stripe   = StripeProcessor()
email    = EmailChannel()
sms      = SMSChannel()
gst18    = TaxCalculator(0.18)   # 18% GST
gst5     = TaxCalculator(0.05)   # 5% GST

# Create orders with COMPOSED components
retail = RetailOrder(
    "ORD001", "Alice",
    payment_proc = razorpay,
    notifier     = email,
    tax_calc     = gst18
)
retail.add_item("Laptop", 75000)
retail.add_item("Bag", 2500)
retail.print_summary()
retail.place()

wholesale = WholesaleOrder(
    "ORD002", "TechCorp Ltd.",
    payment_proc    = stripe,
    notifier        = sms,
    tax_calc        = gst5,
    min_order_value = 50000
)
wholesale.add_item("Laptop", 75000, qty=10)
wholesale.print_summary()
wholesale.place()

# Swap payment processor without changing Order class!
subscription = SubscriptionOrder(
    "ORD003", "Bob",
    payment_proc = stripe,   # different processor
    notifier     = email,
    tax_calc     = gst18,
    frequency    = "weekly"
)
subscription.add_item("Coffee Beans", 800, qty=4)
subscription.print_summary()
subscription.place()
